<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class PaymentCheckout {
 public static function register(): void { add_shortcode('avanik_payment_checkout',[self::class,'render']); add_action('admin_post_avanik_payment_start',[self::class,'start']); add_action('admin_post_nopriv_avanik_payment_start',[self::class,'start']); }
 public static function render(): string { if(!is_user_logged_in()) return '<p>برای پرداخت ابتدا وارد حساب شوید.</p>'; $id=(int)($_GET['booking_id']??0); if(!$id)return '<p>رزروی انتخاب نشده است.</p>'; global $wpdb; $table=BookingRepository::table_name(); $b=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE booking_id=%d AND customer_id=%d",$id,get_current_user_id()),ARRAY_A); if(!$b)return '<p>رزرو پیدا نشد.</p>'; ob_start(); ?><section dir="rtl"><h2>پرداخت رزرو #<?php echo esc_html($id); ?></h2><p>مبلغ: <?php echo esc_html(number_format((float)$b['total_amount']).' '.$b['currency']); ?></p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('avanik_payment_start'); ?><input type="hidden" name="action" value="avanik_payment_start"><input type="hidden" name="booking_id" value="<?php echo esc_attr($id); ?>"><label><input type="radio" name="gateway" value="zarinpal" checked> زرین‌پال</label><br><label><input type="radio" name="gateway" value="card_to_card"> کارت به کارت</label><p><button type="submit">ادامه پرداخت</button></p></form></section><?php return (string)ob_get_clean(); }
 public static function start(): void { if(!is_user_logged_in()||!check_admin_referer('avanik_payment_start'))wp_die('Unauthorized'); global $wpdb; $id=(int)($_POST['booking_id']??0); $b=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.BookingRepository::table_name().' WHERE booking_id=%d AND customer_id=%d',$id,get_current_user_id()),ARRAY_A); if(!$b)wp_die('Booking not found'); $gateway=sanitize_key(wp_unslash($_POST['gateway']??'zarinpal')); if(!in_array($gateway,['zarinpal','card_to_card'],true))wp_die('Unsupported payment method'); $payment=PaymentService::create_for_booking($id,get_current_user_id(),(float)$b['total_amount'],$b['currency'],$gateway); if(!$payment)wp_die('Unable to create payment'); wp_safe_redirect(home_url('/payment/?payment_id='.$payment)); exit; }
}